/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agent harness ---------- */
/* a whole agent app in one card: chats down the side, tabs across the top, a New chat home with suggestions, and the
   conversations themselves, told with the components above */
.card.wide .stage-in:has(>.ahx){max-width:960px}
/* the side's columns (owner, 18 Nov): its rows' fills sit 8px in from its edges and their words 16px in, under the workspace's
   tile; New chat's pencil is centred under the tile and its words start where the workspace's name does; the side's buttons
   and the chats' marks end on one right edge, the glyphs centred over the marks. The workspace switcher shares the tab strip's
   centre line, and a hover is a quiet fill that shows in light mode on whatever it sits on */
.ahx{display:flex;height:620px;overflow:hidden;container:ahx/inline-size;text-align:left;position:relative;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.ahx-side{flex:none;width:236px;display:flex;flex-direction:column;gap:2px;padding:10px;background:var(--dm-surface);border-right:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);transition:margin-left var(--dm-t) var(--dm-ease),transform var(--dm-t) var(--dm-ease),box-shadow var(--dm-t) var(--dm-ease)}
.ahx.ns .ahx-side{margin-left:-236px}
.ahx-ws{display:flex;align-items:center;gap:2px;margin-bottom:6px}
.ahx-wsb{flex:1;min-width:0;display:flex;align-items:center;gap:9px;height:34px;padding:0 var(--dm-s-2) 0 7px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13.5px;font-weight:500;color:var(--dm-fg);transition:background var(--dm-t-fast)}
.ahx-wsb[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.ahx-wsb:hover{background:var(--dm-row)}}
.ahx-wsb .t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ahx-wsb>.i{color:var(--dm-muted);transition:transform var(--dm-t) var(--dm-ease)}
.ahx-wsb[aria-expanded="true"]>.i{transform:rotate(180deg)}
/* the up-and-down icon of a switcher never flips: its two chevrons move a little apart while you point at it or its menu is
   open (owner, 8 Nov) */
.ahx-wsb[aria-expanded="true"]>.i:has(use[href$="i-unfold"]){transform:none}
svg.i:has(>use[href$="i-unfold"]){transition:transform .2s cubic-bezier(.22,1,.36,1)}
@media (hover:hover) and (pointer:fine){:is(button,[role="button"]):is(:hover,[aria-expanded="true"]) svg.i:has(>use[href$="i-unfold"]){transform:scaleY(1.22)}}
.ahx-lg{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;flex:none;background:var(--dm-ink);color:var(--dm-on-ink);font-size:11px;font-weight:500;transition:background var(--dm-t) var(--dm-ease)}
.ahx-ws .ib,.ahx-top>.ib,.ahx-lh .ib{width:28px;height:28px;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.ahx-ws .ib:hover,.ahx-top>.ib:hover,.ahx-lh .ib:hover{color:var(--dm-fg)}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.ahx :is(.ib,.pill):active,:root[data-style="clean"] .ahx .ib:active,:root [data-style="clean"] .ahx .ib:active,:root [data-style="clean"].ahx .ib:active{transform:none}
.ahx-wsp{width:212px}
.ahx-wsp .ahx-lg{width:18px;height:18px;font-size:10px}
.ahx-nav,.ahx-cv{display:flex;align-items:center;gap:9px;width:100%;min-height:32px;padding:0 9px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;color:var(--dm-fg2);transition:background var(--dm-t-fast),box-shadow var(--dm-t-fast),color var(--dm-t-fast)}
.ahx-nav{color:var(--dm-fg);font-weight:500}
.ahx-nav .i{color:var(--dm-fg2)}
@media (hover:hover) and (pointer:fine){.ahx-nav:hover,.ahx-cv:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ahx-cv[aria-current="true"]{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent),0 1px 2px rgba(0,0,0,.04)}
.ahx-cv .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* the chats fill the scrolling list, and a tab clips its own button: their rings are drawn inside */
.ahx-cv:focus-visible,.ahx-tb:focus-visible{outline-offset:-2px}
.ahx-lh{display:flex;align-items:center;justify-content:space-between;padding:var(--dm-s-3) 1px 2px 9px;font-size:11.5px;color:var(--dm-muted)}
.ahx-lh .ib{width:24px;height:24px}
/* the harness's own side (the templates borrow these classes and keep their own measures): its rows' fills 8px in from its
   edges, its words 16px in under the workspace's tile, New chat's pencil centred under the tile and its words under the
   workspace's name, and the side's buttons ending where the chats' marks do */
.ahx>.ahx-side{padding:var(--dm-s-2)}
.ahx .ahx-ws{height:30px;margin-bottom:var(--dm-s-2)}
.ahx .ahx-wsb{height:30px;padding:0 var(--dm-s-2)}
.ahx :is(.ahx-nav,.ahx-cv){padding:0 7px 0 var(--dm-s-2)}
.ahx .ahx-nav{padding-left:11px;gap:12px}
.ahx .ahx-lh{padding:var(--dm-s-3) 2px 2px var(--dm-s-2)}
.ahx-si{display:block;width:100%;height:32px;margin:var(--dm-s-1) 0 6px;padding:0 var(--dm-s-2);border:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13px;outline:0;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.ahx-si{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.ahx-si:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.ahx-si::placeholder{color:var(--dm-muted)}
.ahx-si::-webkit-search-cancel-button{display:none}
.ahx-list{flex:1;min-height:0;display:flex;flex-direction:column;gap:2px;overflow-y:auto;scrollbar-width:none}
.ahx-none{margin:0;padding:6px var(--dm-s-2);font-size:12.5px;color:var(--dm-muted)}
.ahx-mk{display:grid;place-items:center;width:14px;flex:none}
.ahx-mk:empty{display:none}
.ahx-mk .spin{width:10px;height:10px;color:var(--dm-muted)}
.ahx-main{flex:1;min-width:0;display:flex;flex-direction:column;position:relative;container:ahm/inline-size}
/* the tabs: a chat opens or comes to the front, × closes it, + opens New chat */
.ahx-top{flex:none;display:flex;align-items:center;gap:var(--dm-s-1);height:47px;padding:0 9px 0 6px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ahx-menu{display:none}
.ahx.ns .ahx-menu{display:inline-grid;margin-left:2px}
.ahx-tabs{position:relative;display:flex;align-items:center;gap:2px;min-width:0;padding:2px;overflow-x:auto;scrollbar-width:none}
.ahx-tabs::-webkit-scrollbar{display:none}
.ahx-tab{flex:0 1 164px;min-width:108px;display:flex;align-items:center;height:30px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));overflow:hidden;color:var(--dm-fg2);transition:background var(--dm-t-fast),box-shadow var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ahx-tab:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ahx-tab.on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent),0 1px 2px rgba(0,0,0,.04)}
.ahx-tb{flex:1;min-width:0;display:flex;align-items:center;gap:7px;height:100%;padding:0 2px 0 10px;font-size:12.5px;text-align:left}
.ahx-tb .t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ahx-tx{width:20px;height:20px;margin-right:5px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;flex:none;color:var(--dm-muted);opacity:0;transition:opacity var(--dm-t-fast),background var(--dm-t-fast),color var(--dm-t-fast)}
.ahx-tx .i{width:12px;height:12px}
.ahx-tab.on .ahx-tx,.ahx-tx:focus-visible{opacity:1}
@media (hover:hover) and (pointer:fine){.ahx-tab:hover .ahx-tx{opacity:1}}
@media (hover:hover) and (pointer:fine){.ahx-tx:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ahx-plus{flex:none}
.ahx-tn{display:none;place-items:center;flex:none;width:28px;height:28px;border-radius:var(--dm-r-sm);color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.ahx-tn[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.ahx-tn:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ahx-tn .num{display:grid;place-items:center;min-width:18px;height:18px;padding:0 var(--dm-s-1);border-radius:var(--dm-r-tiny,5px);box-shadow:inset 0 0 0 1.5px currentColor;font-size:11px;font-weight:500;line-height:1}
.ahx-tp{width:232px}
.ahx-tp .mi .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ahx-tp .mi .ahx-mk:empty{display:grid}
.ahx-spl{flex:none;margin-left:auto;transition:opacity var(--dm-t) var(--dm-ease)}
.ahx-main.home .ahx-spl{opacity:0;pointer-events:none}
.ahx-spl .spl-pill{height:30px;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ahx-spl .spl-in{gap:7px;padding:0 var(--dm-s-1) 0 11px;font-size:12.5px}
.ahx-spl .spl-in .g{width:14px}
.ahx-spl .spl-in .pill{height:22px;padding:0 9px;margin-left:1px;font-size:12px}
/* New chat, as a chat app opens one: the composer waits at the foot, where a chat's composer sits, and the mark and the
   greeting sit centred in the room above it. The chat on screen and New chat share that room, so the composer never moves */
.ahx-body{flex:1;min-height:0;display:grid;grid-template-rows:minmax(0,1fr) auto;grid-template-columns:minmax(0,1fr);position:relative}
.ahx-feed{grid-area:1/1}
.ahx-bot{grid-area:2/1}
.ahx-home{grid-area:1/1;min-height:0;display:flex;flex-direction:column;justify-content:center;padding:var(--dm-s-5) 28px var(--dm-s-2)}
.ahx-main:not(.home) .ahx-home{display:none}
.ahx-main.home .ahx-feed,.ahx-main.home .ahx-bot::before{visibility:hidden}
.ahx-hw{width:100%;max-width:600px;margin:0 auto;display:flex;flex-direction:column;align-items:center}
.ahx-hi{display:flex;flex-direction:column;align-items:center;text-align:center;padding:0 var(--dm-s-1);font-size:14px;font-weight:500;letter-spacing:-.4px;line-height:1.3}
.ahx-hi span{color:var(--dm-muted)}
.ahx-hi h4{margin:0;font:inherit;color:var(--dm-fg)}
/* the product's mark over the greeting (the DesignMe smiley in the demo; swap in your own) */
.ahx-brand{display:block;flex:none;width:30px;height:25px;margin-bottom:10px;color:var(--dm-fg)}
.ahx-brand>svg{display:block;width:100%;height:100%}
/* a chat scrolls inside the card; each one keeps its own column, only the one on screen takes up room */
.ahx-feed{flex:1;min-height:0;display:flex;flex-direction:column;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--dm-line) transparent}
.ahx-cols{flex:1 0 auto;display:grid}
.ahx-col{grid-area:1/1;min-width:0;width:100%;max-width:688px;margin:0 auto;display:flex;flex-direction:column;gap:var(--dm-s-5);padding:var(--dm-s-6) 28px 30px;transition:opacity var(--dm-t) var(--dm-ease)}
.ahx-col.off{visibility:hidden;height:0;padding-block:0;overflow:hidden}
.ahx-col.ff{opacity:0}
.ahx-say .w{animation:lvw .5s var(--dm-ease) both}
.ahx-fs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}
.ahx-fs:last-child{margin-bottom:0}
.ahx-msg{min-width:0}
/* the person's words end where the composer's send button does: a bubble's words sit 16px in, as the composer's do */
.ahx-col .bub{padding-inline:var(--dm-s-4)}
/* the sources button of an answer in the chat keeps its words on the column's edge when it reaches it (on a phone), its hover
   box reaching out round them; on a phone it ends the row, under the tab strip's last glyph (16px in, as the panel's close is) */
.ahx-col .lva-sb{margin-right:-9px}
/* a component in the chat lines up with the messages on the left, instead of centring itself as it does on its own */
.ahx-col .ahx-msg>*{margin-left:0;margin-right:auto}
/* chat components sit on the chat itself, the way a bare card shows them; an artifact and a diff keep their card */
.ahx-msg:not(.box)>.panel:not(.keep){background:none;box-shadow:none;padding-left:0;padding-right:0;border-radius:0}
/* in the chat a finished question set closes up behind its answers */
.ahx-msg .dpx-body{min-height:0}
.ahx-msg .dpx-f.leave{display:none}
/* the agent's work, gathered under one line that folds away when it is done */
.ahx-wk{display:flex;flex-direction:column;align-items:flex-start}
.ahx-wh{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:28px;padding:0 9px 0 7px;margin-left:-7px;border-radius:var(--dm-r-pill);font-size:13.5px;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ahx-wh:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ahx-wh .g{display:grid;place-items:center;width:14px;color:var(--dm-muted)}
.ahx-wh .g:has(>svg){color:var(--dm-ok)}
:root[data-style="clean"] .ahx-wh .g:has(>svg),:root [data-style="clean"] .ahx-wh .g:has(>svg),:root [data-style="clean"].ahx-wh .g:has(>svg){color:var(--dm-ok-mark)}
.ahx-wh .m{color:var(--dm-muted);font-size:12.5px}
.ahx-wh>.i{color:var(--dm-muted);transition:transform var(--dm-t) var(--dm-ease)}
.ahx-wh[aria-expanded="true"]>.i{transform:rotate(180deg)}
.ahx-wb{align-self:stretch}
.ahx-wl{display:flex;flex-direction:column;gap:var(--dm-s-4);margin:var(--dm-s-2) 0 2px 6px;padding-left:18px;border-left:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ahx-bot{flex:none;position:relative;padding:0 28px 18px}
.ahx-bot::before{content:"";position:absolute;left:0;right:10px;bottom:100%;height:28px;background:linear-gradient(transparent,var(--dm-surface));pointer-events:none}
.ahx-bot .cpx{max-width:632px;margin:0 auto}
.ahx .cpx-thread{display:none}
.ahx .ctm-ft{gap:2px;margin-right:1px;font-size:12.5px}
.ahx .ctm-ft>span{color:var(--dm-muted);margin-right:2px}
/* while the agent works in the chat on screen, a new message waits */
.ahx.busy .cpx-bar .cpx-send{background:var(--dm-rail);color:var(--dm-surface);pointer-events:none}
:root[data-style="clean"] .ahx.busy .cpx-bar .cpx-send,:root [data-style="clean"] .ahx.busy .cpx-bar .cpx-send,:root [data-style="clean"].ahx.busy .cpx-bar .cpx-send{color:var(--dm-surface)}
:root[data-style="clean"] .ahx.busy .cpx-bar .cpx-send::before,:root [data-style="clean"] .ahx.busy .cpx-bar .cpx-send::before,:root [data-style="clean"].ahx.busy .cpx-bar .cpx-send::before{opacity:0}
/* the panel beside the chat, for an artifact */
/* shut, the panel is hidden as well as narrow, so Tab passes over its buttons */
.ahx-pane{flex:none;width:0;overflow:hidden;background:var(--dm-surface);border-left:1px solid transparent;visibility:hidden;transition:width var(--dm-t) var(--dm-ease),border-color var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
.ahx.pn .ahx-pane{width:300px;border-left-color:color-mix(in srgb,var(--dm-line) 50%,transparent);visibility:visible;transition-delay:0s}
.ahx-pi{width:300px;height:100%;display:flex;flex-direction:column}
.ahx-ph{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);height:47px;padding:0 9px 0 var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;font-weight:500}
.ahx-ph .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ahx-ph>.i{color:var(--dm-pb)}
.ahx-ph .ib{width:28px;height:28px;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.ahx-ph .ib:hover{color:var(--dm-fg)}}
.ahx-pb{flex:1;min-height:0;overflow-y:auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);scrollbar-width:thin;scrollbar-color:var(--dm-line) transparent}
.ahx-pn{display:flex;flex-direction:column;gap:var(--dm-s-1);font-size:13px;line-height:1.55;color:var(--dm-fg2)}
.ahx-pn b{font-weight:500;color:var(--dm-fg)}
.ahx-pn p{margin:0 0 10px}
/* the report opened in the panel: drawn flat, with the chart it describes */
/* its words sit on the panel's 16px edges, as the notes under it do; the head already names it, so it has no title of its own */
.ahx-doc{padding:0}
.ahx-dp{font-size:12.5px;line-height:1.5;color:var(--dm-fg2);text-wrap:pretty}
.ahx-kp{display:flex;align-items:baseline;gap:var(--dm-s-2);margin-top:10px}
.ahx-kp b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.ahx-dd{font-size:12px;color:var(--dm-ok)}
.ahx-ch{display:block;width:100%;height:56px;margin-top:var(--dm-s-2);overflow:visible}
.ahx-ch .ln{fill:none;stroke:var(--dm-accent-mark,var(--dm-accent));stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.ahx-ax{position:relative;height:16px;margin-top:6px;font-size:10.5px;line-height:16px;color:var(--dm-muted)}
/* each month's label sits under its own point: the first starts on the chart's left edge and the last ends on its right */
.ahx-ax span{position:absolute;top:0;transform:translateX(-50%);white-space:nowrap}
.ahx-ax span:first-child{transform:none}
.ahx-ax span:last-child{transform:translateX(-100%)}
.ahx-scrim{display:none}
/* a narrow chat, beside the panel or on a phone: the composer keeps only what it needs */
@container ahm (max-width:560px){
  .ahx .ctm-ft>span,.ahx .cpx-bar .cpx-ctx,.ahx-spl .spl-in .m{display:none}
  .ahx-col .lva-src{justify-content:space-between}
}
/* phone: the chats slide in from the side, the tabs fold into one, the panel covers the chat */
@container ahx (max-width:620px){
  .ahx .ahx-side,.ahx.ns .ahx-side{position:absolute;z-index:6;left:0;top:0;bottom:0;width:244px;margin-left:0;background:var(--dm-surface);transform:translateX(-101%)}
  .ahx.dr .ahx-side{transform:none;box-shadow:var(--dm-shadow-pop)}
  .ahx-scrim{display:block;position:absolute;inset:0;z-index:5;background:rgba(0,0,0,.2);opacity:0;pointer-events:none;transition:opacity var(--dm-t) var(--dm-ease)}
  .ahx.dr .ahx-scrim{opacity:1;pointer-events:auto}
  .ahx .ahx-menu{display:inline-grid;margin-left:2px}
  .ahx-top{padding:0 9px 0 6px}
  .ahx-spl{display:none}
  /* the tabs fold into one: the chat on screen fills the row, and a count of the open chats lists them all */
  .ahx-tabs{flex:1}
  .ahx-tab:not(.on){display:none}
  .ahx-tab.on{flex:1 1 auto;min-width:0}
  .ahx-tn:not([hidden]){display:grid}
  .ahx-side{visibility:hidden;transition:transform var(--dm-t) var(--dm-ease),box-shadow var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
  .ahx.dr .ahx-side{visibility:visible;transition-delay:0s}
  .ahx-pane{visibility:hidden;transition:width var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
  .ahx.pn .ahx-pane{visibility:visible;transition-delay:0s}
  .ahx-home{padding:var(--dm-s-4) 10px var(--dm-s-2)}
  .ahx-col{padding:18px var(--dm-s-4) var(--dm-s-6)}
  .ahx-bot{padding:0 var(--dm-s-4) var(--dm-s-4)}
  .ahx-pane{position:absolute;z-index:4;top:0;right:0;bottom:0;border-left:0}
  .ahx.pn .ahx-pane{width:100%}
  .ahx-pi{width:100%}
}
/* Clean (owner, 18 Nov): an app screen as Clean draws one. The chats down the side, the tab strip and the panel's head are
   off-white strips over the white chat, edged with a hairline. In the strips every control is 28px and sits 8px from the
   strip's edges: the workspace switcher, the tabs (pills, the open one white with a hairline, as the open chat is), +, the
   status pill and the panel's buttons */
:root[data-style="clean"] .ahx>.ahx-side,:root [data-style="clean"] .ahx>.ahx-side,:root [data-style="clean"].ahx>.ahx-side{background:var(--dm-strip);border-right-color:var(--dm-line)}
:root[data-style="clean"] .ahx .ahx-ws,:root [data-style="clean"] .ahx .ahx-ws,:root [data-style="clean"].ahx .ahx-ws{height:28px}
:root[data-style="clean"] .ahx .ahx-wsb,:root [data-style="clean"] .ahx .ahx-wsb,:root [data-style="clean"].ahx .ahx-wsb{height:28px}
:root[data-style="clean"] :is(.ahx-top,.ahx-ph),:root [data-style="clean"] :is(.ahx-top,.ahx-ph),:root [data-style="clean"]:is(.ahx-top,.ahx-ph){height:45px;background:var(--dm-strip);border-bottom-color:var(--dm-line)}
